/* ==========================================================================
   APF Global Foresight Wiki — MediaWiki:Common.css
   Custom Modern Design System for Futurepedia (futurepedia.mywikis.wiki)
   Stewarded by the Association of Professional Futurists (APF)
   ========================================================================== */

/* 1. Global Typography & Font Imports */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Newsreader:ital,opsz,wght@0,6..72,400;0,6..72,600;1,6..72,400&display=swap');

:root {
  --apf-navy: #0f172a;
  --apf-blue: #1e3a8a;
  --apf-cyan: #0284c7;
  --apf-accent: #38bdf8;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --bg-page: #f8fafc;
  --bg-card: #ffffff;
  --border-light: #e2e8f0;
  --border-subtle: #f1f5f9;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 14px rgba(0,0,0,0.07);
  --shadow-lg: 0 12px 30px rgba(0,0,0,0.1);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
}

/* 2. Global Body & Typography Overrides */
body, #mw-page-base, #mw-head-base {
  background-color: var(--bg-page) !important;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif !important;
  color: var(--text-main) !important;
  line-height: 1.72 !important;
  -webkit-font-smoothing: antialiased;
}

/* Vector Skin Content Card Container */
#content {
  background: var(--bg-card) !important;
  border: 1px solid var(--border-light) !important;
  border-radius: var(--radius-lg) !important;
  box-shadow: var(--shadow-md) !important;
  margin-top: 16px !important;
  margin-bottom: 32px !important;
  padding: 36px 44px !important;
}

/* Headings */
h1, h2, h3, h4, h5, h6, .mw-first-heading {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif !important;
  font-weight: 700 !important;
  color: var(--apf-navy) !important;
  letter-spacing: -0.02em !important;
}

.firstHeading, .mw-first-heading {
  font-size: 2.25em !important;
  font-weight: 800 !important;
  border-bottom: 2px solid var(--border-light) !important;
  padding-bottom: 12px !important;
  margin-bottom: 20px !important;
  line-height: 1.25 !important;
}

h2 {
  font-size: 1.5em !important;
  border-bottom: 1px solid var(--border-light) !important;
  padding-bottom: 8px !important;
  margin-top: 1.8em !important;
  margin-bottom: 0.8em !important;
}

h3 {
  font-size: 1.2em !important;
  margin-top: 1.4em !important;
  margin-bottom: 0.6em !important;
  color: #1e3a8a !important;
}

/* Paragraphs & Text Flow */
#mw-content-text p {
  font-size: 15.5px !important;
  line-height: 1.74 !important;
  margin-bottom: 1.2em !important;
  color: #334155 !important;
}

/* 3. Modernized Links */
#mw-content-text a {
  color: #0369a1 !important;
  text-decoration: none !important;
  font-weight: 500 !important;
  transition: color 0.15s ease, text-decoration-color 0.15s ease !important;
}

#mw-content-text a:hover {
  color: #0284c7 !important;
  text-decoration: underline !important;
}

#mw-content-text a.new {
  color: #dc2626 !important;
}

/* 4. Table of Contents (TOC) Modernization */
#toc, .toc {
  background: #f8fafc !important;
  border: 1px solid var(--border-light) !important;
  border-radius: var(--radius-md) !important;
  padding: 16px 20px !important;
  margin: 1.5em 0 !important;
  box-shadow: var(--shadow-sm) !important;
}

#toctitle, .toctitle h2 {
  font-size: 14px !important;
  font-weight: 700 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.8px !important;
  color: var(--text-muted) !important;
  margin-bottom: 8px !important;
  border: none !important;
}

#toc ul {
  list-style: none !important;
  margin-left: 0 !important;
  padding-left: 0 !important;
}

#toc li {
  margin: 6px 0 !important;
  font-size: 13.5px !important;
}

.tocnumber {
  color: var(--apf-cyan) !important;
  font-weight: 600 !important;
  margin-right: 6px !important;
}

/* 5. Modern Executive Wikitables */
table.wikitable {
  background-color: var(--bg-card) !important;
  border: 1px solid var(--border-light) !important;
  border-collapse: separate !important;
  border-spacing: 0 !important;
  border-radius: var(--radius-md) !important;
  overflow: hidden !important;
  margin: 1.5em 0 !important;
  box-shadow: var(--shadow-sm) !important;
  width: 100% !important;
}

table.wikitable > tr > th, table.wikitable > * > tr > th {
  background: linear-gradient(180deg, #f8fafc 0%, #f1f5f9 100%) !important;
  color: var(--apf-navy) !important;
  font-size: 12.5px !important;
  font-weight: 700 !important;
  text-transform: uppercase !important;
  letter-spacing: 0.5px !important;
  padding: 12px 16px !important;
  border: none !important;
  border-bottom: 2px solid var(--border-light) !important;
  text-align: left !important;
}

table.wikitable > tr > td, table.wikitable > * > tr > td {
  padding: 12px 16px !important;
  border: none !important;
  border-bottom: 1px solid var(--border-subtle) !important;
  font-size: 14px !important;
  line-height: 1.55 !important;
  vertical-align: top !important;
}

table.wikitable > tr:last-child > td, table.wikitable > * > tr:last-child > td {
  border-bottom: none !important;
}

table.wikitable > tr:hover > td, table.wikitable > * > tr:hover > td {
  background-color: #f8fafc !important;
}

/* 6. APF Infoboxes (Methods, Concepts, Thinkers, Case Studies) */
.infobox {
  float: right !important;
  clear: right !important;
  width: 320px !important;
  background: var(--bg-card) !important;
  border: 1px solid var(--border-light) !important;
  border-radius: var(--radius-lg) !important;
  box-shadow: var(--shadow-md) !important;
  margin: 0 0 1.5em 1.8em !important;
  padding: 0 !important;
  overflow: hidden !important;
  font-size: 13.5px !important;
  border-spacing: 0 !important;
  border-collapse: collapse !important;
}

.infobox th.infobox-header, .infobox caption {
  background: linear-gradient(135deg, var(--apf-navy) 0%, var(--apf-blue) 100%) !important;
  color: white !important;
  font-size: 16px !important;
  font-weight: 700 !important;
  padding: 14px 16px !important;
  text-align: center !important;
  letter-spacing: -0.01em !important;
}

.infobox-image {
  text-align: center !important;
  padding: 12px !important;
  background: #f8fafc !important;
  border-bottom: 1px solid var(--border-light) !important;
}

.infobox th {
  width: 38% !important;
  background: #f8fafc !important;
  color: var(--text-muted) !important;
  font-weight: 600 !important;
  padding: 8px 12px !important;
  border-top: 1px solid var(--border-subtle) !important;
  text-align: left !important;
  font-size: 12.5px !important;
}

.infobox td {
  padding: 8px 12px !important;
  border-top: 1px solid var(--border-subtle) !important;
  color: var(--text-main) !important;
}

/* 7. APF Core Competency Badges */
.competency-tag, .apf-badge {
  display: inline-flex !important;
  align-items: center !important;
  gap: 6px !important;
  padding: 4px 10px !important;
  border-radius: 20px !important;
  font-size: 11.5px !important;
  font-weight: 600 !important;
  letter-spacing: 0.2px !important;
  text-transform: uppercase !important;
  margin-bottom: 8px !important;
  border: 1px solid transparent !important;
}

.tag-Framing   { background: #f0f9ff !important; color: #0369a1 !important; border-color: #bae6fd !important; }
.tag-Scanning  { background: #fffbeb !important; color: #b45309 !important; border-color: #fde68a !important; }
.tag-Futuring  { background: #f5f3ff !important; color: #6d28d9 !important; border-color: #ddd6fe !important; }
.tag-Designing { background: #ecfdf5 !important; color: #047857 !important; border-color: #a7f3d0 !important; }
.tag-Adapting  { background: #fff7ed !important; color: #c2410c !important; border-color: #fed7aa !important; }
.tag-Leading   { background: #fdf2f8 !important; color: #be185d !important; border-color: #fbcfe8 !important; }

/* 8. Modern Callouts & Blockquotes */
blockquote {
  border-left: 4px solid var(--apf-cyan) !important;
  background: #f0f9ff !important;
  padding: 14px 20px !important;
  border-radius: 0 var(--radius-md) var(--radius-md) 0 !important;
  margin: 1.5em 0 !important;
  font-family: 'Newsreader', Georgia, serif !important;
  font-size: 17px !important;
  font-style: italic !important;
  color: #0c4a6e !important;
  line-height: 1.6 !important;
}

/* 9. Vector Sidebar & Navigation Modernization */
#mw-panel {
  padding-top: 20px !important;
  width: 175px !important;
}

.portal h3 {
  font-size: 11px !important;
  text-transform: uppercase !important;
  letter-spacing: 1px !important;
  color: var(--text-muted) !important;
  font-weight: 700 !important;
  margin-bottom: 6px !important;
  padding: 4px 8px !important;
}

.portal .body li {
  padding: 4px 0 !important;
}

.portal .body li a {
  color: #475569 !important;
  font-size: 13px !important;
  transition: color 0.15s ease !important;
}

.portal .body li a:hover {
  color: var(--apf-cyan) !important;
  text-decoration: none !important;
}

/* 10. Vector Search Box Modernization */
#simpleSearch {
  background: white !important;
  border: 1px solid var(--border-light) !important;
  border-radius: 20px !important;
  padding: 2px 10px !important;
  box-shadow: var(--shadow-sm) !important;
  transition: all 0.2s ease !important;
}

#simpleSearch:focus-within {
  border-color: var(--apf-cyan) !important;
  box-shadow: 0 0 0 3px rgba(2, 132, 199, 0.15) !important;
}

#searchInput {
  font-family: 'Inter', sans-serif !important;
  font-size: 13px !important;
  color: var(--text-main) !important;
}

/* 11. Vector Tabs (Page, Discussion, Edit, History) */
.vectorTabs {
  background: transparent !important;
  margin-right: 12px !important;
}

.vectorTabs ul li {
  background: transparent !important;
  border: none !important;
  margin: 0 4px !important;
}

.vectorTabs ul li a {
  border-radius: 8px !important;
  padding: 6px 14px !important;
  font-size: 13px !important;
  font-weight: 500 !important;
  color: var(--text-muted) !important;
  background: rgba(255, 255, 255, 0.6) !important;
  border: 1px solid var(--border-light) !important;
  transition: all 0.15s ease !important;
}

.vectorTabs ul li.selected a {
  background: var(--apf-navy) !important;
  color: white !important;
  border-color: var(--apf-navy) !important;
  font-weight: 600 !important;
}

.vectorTabs ul li a:hover {
  background: white !important;
  color: var(--apf-cyan) !important;
  border-color: var(--apf-cyan) !important;
}

/* 12. Category Links Bar (#catlinks) */
#catlinks {
  background: #f8fafc !important;
  border: 1px solid var(--border-light) !important;
  border-radius: var(--radius-md) !important;
  padding: 12px 16px !important;
  margin-top: 32px !important;
}

#catlinks li {
  border: none !important;
  display: inline-block !important;
  margin: 2px 4px !important;
}

#catlinks li a {
  background: white !important;
  border: 1px solid var(--border-light) !important;
  border-radius: 14px !important;
  padding: 3px 10px !important;
  font-size: 12px !important;
  color: var(--text-muted) !important;
}

#catlinks li a:hover {
  background: var(--apf-navy) !important;
  color: white !important;
  border-color: var(--apf-navy) !important;
}

/* 13. Footer Styling */
#footer {
  margin-top: 40px !important;
  padding: 24px 0 !important;
  border-top: 1px solid var(--border-light) !important;
  color: var(--text-muted) !important;
  font-size: 12px !important;
}

/* 14. APF Official Branding & Embedded Insignia */
/* Sidebar Site Logo (#p-logo) */
#p-logo {
  margin-bottom: 1.2em !important;
  text-align: center !important;
}

#p-logo a {
  background-image: url("data:image/png;base64,") !important;
  background-size: 135px auto !important;
  background-position: center 10px !important;
  background-repeat: no-repeat !important;
  height: 140px !important;
  width: 155px !important;
  display: block !important;
  margin: 0 auto !important;
  transition: transform 0.2s cubic-bezier(0.4, 0, 0.2, 1) !important;
}

#p-logo a:hover {
  transform: scale(1.04) !important;
}

/* Main Page Hero Banner Logo (.apf-main-logo) */
.apf-main-logo {
  width: 105px !important;
  height: 105px !important;
  background-image: url("data:image/png;base64,") !important;
  background-size: contain !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  display: inline-block !important;
  filter: drop-shadow(0 6px 16px rgba(0, 0, 0, 0.35)) !important;
  vertical-align: middle !important;
}

/* Broken Image Red Link Suppression */
a.new[title^="File:"] {
  display: inline-flex !important;
  align-items: center !important;
  padding: 4px 10px !important;
  background: #f1f5f9 !important;
  border: 1px dashed #cbd5e1 !important;
  border-radius: 6px !important;
  color: #64748b !important;
  font-size: 12px !important;
  text-decoration: none !important;
}

a.new[title^="File:"]::before {
  content: "🖼️ " !important;
  margin-right: 4px !important;
}
